// Week search: suggest free slots within +/-3 days of the requested time.
// Timezone-safe: all parsing/formatting via Luxon in Europe/Madrid,
// so the offset is +02:00 in summer and +01:00 in winter automatically.
const TZ = 'Europe/Madrid';
const args = $('Webhook').first().json?.body?.args || {};
const reqTimeStr = args.required_time || args.local_time;

function parseMadrid(s) {
  if (!s) return null;
  // If the string has an explicit offset/Z it is respected, otherwise it is
  // interpreted as Madrid wall-clock time; result is always in Madrid zone.
  const dt = DateTime.fromISO(String(s), { zone: TZ });
  return dt.isValid ? dt : null;
}

const target = parseMadrid(reqTimeStr) || DateTime.now().setZone(TZ);

const SLOT_MINUTES = 30;
const SLOTS_NEEDED = 2;
const WORK_START_HOUR = 10;
const WORK_END_HOUR_DEFAULT = 20;
const WORK_END_HOUR_FRIDAY = 15;

const busyEvents = $input.all().map(item => ({
  start: DateTime.fromISO(item.json.start?.dateTime || item.json.start?.date, { zone: TZ }),
  end: DateTime.fromISO(item.json.end?.dateTime || item.json.end?.date, { zone: TZ })
})).filter(e => e.start.isValid && e.end.isValid);

const now = DateTime.now().setZone(TZ);

let day = target.minus({ days: 3 }).set({ hour: WORK_START_HOUR, minute: 0, second: 0, millisecond: 0 });

const allValidSlots = [];

for (let i = 0; i < 7; i++) {
  const dow = day.weekday; // Luxon: 1=Mon ... 7=Sun
  if (dow <= 5) {
    const endHour = dow === 5 ? WORK_END_HOUR_FRIDAY : WORK_END_HOUR_DEFAULT;
    let t = day;
    while (t.hour < endHour) {
      const slotEnd = t.plus({ minutes: SLOT_MINUTES });
      const isFree = !busyEvents.some(e => t < e.end && slotEnd > e.start);
      if (isFree && t > now) {
        allValidSlots.push({ dt: t, start: t.toISO({ suppressMilliseconds: true }) });
      }
      t = slotEnd;
    }
  }
  day = day.plus({ days: 1 }).set({ hour: WORK_START_HOUR, minute: 0, second: 0, millisecond: 0 });
}

allValidSlots.sort((a, b) =>
  Math.abs(a.dt.toMillis() - target.toMillis()) - Math.abs(b.dt.toMillis() - target.toMillis())
);

const foundSlots = allValidSlots.slice(0, SLOTS_NEEDED).map(s => ({ start: s.start }));

return [{ json: { suggested_slots: foundSlots, message: "Week search completed." } }];

