// Choose which same-name event to act on.
// Priority: 1) exact appointment code in summary [XXXX]
//           2) exact start-time match
//           3) exactly ONE candidate -> safe to take it
//           4) multiple candidates, nothing matched -> AMBIGUOUS (ask patient)
//           5) none -> APPOINTMENT_NOT_FOUND
// Timezone-safe: requested time parsed via Luxon in Europe/Madrid (DST-aware).
const items = $input.all();
if (!items.length) return [{ json: {} }];
const args = $('Webhook').first().json?.body?.args || {};
const code = (args.appointment_id || '').toString().trim();
let chosen = null;
if (code) {
  chosen = items.find(it => (it.json.summary || '').includes('[' + code + ']') || new RegExp('CODE:\\s*' + code + '(\\D|$)').test(it.json.description || ''));
}
if (!chosen) {
  const req = args.time1;
  const reqDt = req ? DateTime.fromISO(String(req), { zone: 'Europe/Madrid' }) : null;
  const reqMs = reqDt && reqDt.isValid ? reqDt.toMillis() : NaN;
  if (!isNaN(reqMs)) {
    chosen = items.find(it => {
      const s = it.json.start?.dateTime || it.json.start?.date;
      return s && Math.abs(new Date(s).getTime() - reqMs) < 60000;
    });
  }
}
if (!chosen) {
  if (items.length === 1) {
    chosen = items[0]; // single candidate: safe even without code/time match
  } else {
    // Multiple same-name events and no reliable match -> never guess.
    return [{ json: { _ambiguous: true, candidates: items.length } }];
  }
}
return [{ json: chosen.json }];

