// Read the day's existing events; pick a 4-digit code (1000-9999) NOT already used that day.
const events = $input.all();
const used = new Set();
for (const e of events) {
  const text = ((e.json && e.json.summary) ? e.json.summary : '') + '\n' + ((e.json && e.json.description) ? e.json.description : '');
  const m = text.match(/\[(\d{4})\]/);
  if (m) used.add(m[1]);
  const m2 = text.match(/CODE:\s*(\d{4})/);
  if (m2) used.add(m2[1]);
}
let code = String(Math.floor(1000 + Math.random() * 9000));
let attempts = 0;
while (used.has(code) && attempts < 100) {
  code = String(Math.floor(1000 + Math.random() * 9000));
  attempts++;
}
return [{ json: { appointment_code: code, codes_used_today: used.size } }];
